import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// Capa de Modelo encargada de administrar la colección polimórfica y su lógica de negocio asociada
public class CatalogoIntegraciones {
    // Lista polimórfica que almacena cualquier clase que extienda de AbstractIntegracion
    private List<AbstractIntegracion> listaIntegraciones;

    public CatalogoIntegraciones() {
        this.listaIntegraciones = new ArrayList<>();
        cargarIntegracionesIniciales();
    }

    // Método privado para inicializar datos heterogéneos de prueba en el catálogo
    private void cargarIntegracionesIniciales() {
        listaIntegraciones.add(new PasarelaTarjetaCredito("TC-01", "VisaNet", "ACTIVO", 120.5, "Crédito"));
        listaIntegraciones.add(new ProveedorLogisticaEnvio("ENV-01", "CargoExpress", "ACTIVO", 350.0, "Nacional", true));
        listaIntegraciones.add(new PasarelaTarjetaCredito("TC-02", "MasterPay", "ACTIVO", 95.0, "Débito"));
        listaIntegraciones.add(new ProveedorLogisticaEnvio("ENV-02", "DHL Global", "MANTENIMIENTO", 450.2, "Internacional", false));
        listaIntegraciones.add(new BilleteraDigital("BIL-01", "PayPal API", "ACTIVO", 110.0, "PayPal"));
        listaIntegraciones.add(new CertificadorFELOnline("FEL-01", "Infile FEL", "ACTIVO", 210.0, "123456-7"));
    }

    public void agregarIntegracion(AbstractIntegracion integracion) {
        listaIntegraciones.add(integracion);
    }

    // Búsqueda secuencial de un elemento por su identificador único (ignorando mayúsculas/minúsculas)
    public AbstractIntegracion buscarPorIdentificador(String id) {
        for (AbstractIntegracion i : listaIntegraciones) {
            if (i.getIdentificador().equalsIgnoreCase(id)) {
                return i;
            }
        }
        return null; // Retorna null si no se encuentra coincidencia
    }

    // Ordenamiento natural de la lista invocando al método compareTo de la clase abstracta
    public void ordenarPorLatencia() {
        Collections.sort(listaIntegraciones);
    }

    public List<AbstractIntegracion> getListaIntegraciones() {
        return listaIntegraciones;
    }
}
